package com.firecap.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.provider.MediaStore;import android.content.ContentValues;import android.net.Uri;import android.view.*;import android.widget.*;import java.io.*;import java.security.*;import java.security.spec.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 private EditText ip;private TextView status;private ImageView preview;private byte[] latest;private AdbClient connection;private String connectedHost;private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private Button button(String s){Button b=new Button(this);b.setText(s);b.setTextColor(-1);b.setAllCaps(false);b.setTextSize(16);android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(0xff087e83);bg.setCornerRadius(22);b.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,120);lp.setMargins(0,12,0,12);b.setLayoutParams(lp);return b;}
 public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(40,55,40,40);root.setBackgroundColor(0xff10151e);ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);TextView title=new TextView(this);title.setText("▣  FIRECAP");title.setTextSize(34);title.setTextColor(0xff36c7bd);root.addView(title);TextView sub=new TextView(this);sub.setText("Fire TV screenshot studio  •  JPG capture");sub.setTextColor(0xffa7bac6);sub.setTextSize(14);sub.setPadding(0,12,0,35);root.addView(sub);ip=new EditText(this);ip.setTextColor(-1);ip.setHintTextColor(0xff9a9a9a);ip.setHint("Fire TV IP address");ip.setSingleLine(true);ip.setText(getPreferences(0).getString("ip",""));ip.setPadding(20,25,20,25);root.addView(ip);status=new TextView(this);status.setTextColor(-1);status.setText("Enable ADB debugging on Fire TV; both devices must use the same Wi-Fi.");root.addView(status);Button capture=button("Capture screenshot");root.addView(capture);preview=new ImageView(this);preview.setAdjustViewBounds(true);preview.setMinimumHeight(260);preview.setBackgroundColor(0xff1e2937);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);root.addView(preview);Button save=button("Save JPG to phone");root.addView(save);capture.setOnClickListener(v->capture());save.setOnClickListener(v->save());}
 private KeyPair key()throws Exception{android.content.SharedPreferences p=getPreferences(0);String priv=p.getString("priv",null),pub=p.getString("pub",null);if(priv==null||pub==null){KeyPair kp=AdbClient.newKey();p.edit().putString("priv",android.util.Base64.encodeToString(kp.getPrivate().getEncoded(),2)).putString("pub",android.util.Base64.encodeToString(kp.getPublic().getEncoded(),2)).apply();return kp;}KeyFactory f=KeyFactory.getInstance("RSA");return new KeyPair(f.generatePublic(new X509EncodedKeySpec(android.util.Base64.decode(pub,2))),f.generatePrivate(new PKCS8EncodedKeySpec(android.util.Base64.decode(priv,2))));}
 private void tell(String s){runOnUiThread(()->status.setText(s));}
 private void capture(){String host=ip.getText().toString().trim();if(host.isEmpty()){tell("Enter the Fire TV IP address");return;}getPreferences(0).edit().putString("ip",host).apply();tell("Connecting to Fire TV...");worker.execute(()->{try{if(connection==null||!host.equals(connectedHost)){disconnect();connection=new AdbClient(host,5555,key());connectedHost=host;}byte[] png;try{png=connection.screenshot();}catch(Exception first){disconnect();connection=new AdbClient(host,5555,key());connectedHost=host;png=connection.screenshot();}Bitmap b=BitmapFactory.decodeByteArray(png,0,png.length);if(b==null)throw new IOException("Image decoding failed");ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.JPEG,82,out);latest=out.toByteArray();runOnUiThread(()->preview.setImageBitmap(b));tell("Captured JPG ("+latest.length/1024+" KB)");}catch(Exception e){disconnect();tell("Connection failed: "+e.getMessage());}});}
 private void disconnect(){if(connection!=null){try{connection.close();}catch(Exception ignored){}connection=null;connectedHost=null;}}
 @Override protected void onDestroy(){worker.execute(()->disconnect());worker.shutdown();super.onDestroy();}
 private void save(){if(latest==null){tell("Capture an image first");return;}byte[] data=latest.clone();worker.execute(()->{try{ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,"FIRECAP_"+System.currentTimeMillis()+".jpg");v.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/FIRECAP");Uri uri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);if(uri==null)throw new IOException("Cannot create image");try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(data);}tell("JPG saved in Pictures/FIRECAP");}catch(Exception e){tell("Save failed: "+e.getMessage());}});}
}